// Golden-file tests for ExportDiscussion using the Pi parser.
//
// Golden files are generated by record-trace (go generate). To regenerate:
//
//	go generate ./backend/internal/agent/pi/...

package pi_test

import (
	"testing"

	"github.com/caic-xyz/caic/backend/internal/agent/agenttest"
	"github.com/caic-xyz/caic/backend/internal/agent/pi"
)

func TestExportDiscussionGolden(t *testing.T) {
	t.Parallel()
	agenttest.RunExportDiscussionGolden(t, func() agenttest.Parser {
		return pi.New("", nil).NewWire().ParseMessage
	})
}
